def annot(eid):
    """The hygienised annotation (2.3). phase1c/ is never written; hygiene is applied in memory."""
    if eid not in _ANN:
        a = raw_annot(eid)
        if a and HYGIENE:
            a = hyg.hygienise(a, SK_OF.get(eid))[0]
        _ANN[eid] = a or {}
    return _ANN[eid]

